const WORKER_MJS: &[u16] = &[119, 111, 114, 107, 101, 114, 46, 109, 106, 115];

#[test]
fn differential_matches_ts_loader() {
    for case in CASES {
        let root = decode_tree(case.tagged.as_bytes())
            .unwrap_or_else(|e| panic!("{}: decode failed: {e}", case.id));
        match validate_artifact(&root, "fixture.artifact.json") {
            Ok(validated) => {
                if case.id == "valid" {
                    assert_eq!(validated.modules.len(), 2, "valid: modules");
                    assert_eq!(validated.callables.len(), 2, "valid: callables");
                    assert_eq!(validated.operations.len(), 1, "valid: operations");
                    assert_eq!(validated.pages.len(), 1, "valid: pages");
                    assert_eq!(validated.requires, 1, "valid: requires");
                    assert_eq!(validated.tests, 1, "valid: tests");
                    assert!(
                        validated.module_paths.contains(WORKER_MJS),
                        "valid: worker.mjs indexed"
                    );
                }
                match case.identity_override {
                    Some(_) => {
                        let err = assert_compiled_identity(
                            &root,
                            &expectation_with(case.identity_override),
                        )
                        .expect_err(&format!("{}: identity should fail", case.id));
                        assert_eq!(
                            Some(err.message.as_str()),
                            case.ts_error,
                            "{}: identity message",
                            case.id
                        );
                    }
                    None => assert_eq!(
                        None, case.ts_error,
                        "{}: rust accepted but TS said {:?}",
                        case.id, case.ts_error
                    ),
                }
            }
            Err(err) => assert_eq!(
                Some(err.message.as_str()),
                case.ts_error,
                "{}: first-failure message",
                case.id
            ),
        }
    }
}

#[test]
fn identity_accepts_exact_bindings() {
    let valid = CASES.iter().find(|c| c.id == "valid").unwrap();
    let root = decode_tree(valid.tagged.as_bytes()).unwrap();
    validate_artifact(&root, "fixture.artifact.json").unwrap();
    assert_compiled_identity(&root, &expectation_with(None)).unwrap();
}
